theorem calibrate_needs_client (env : Env) (st : DevState) {w}
    (h : dev_transition env st .Calibrate = ok (w, Outcome.Forward)) :
    env.client_connected = true

theorem info_needs_ready (env : Env) (st : DevState) {w o}
    (h : dev_transition env st .ReadInfo = ok (w, o)) :
    o = Outcome.Read → env.info_ready = true

theorem wifi_update_resets (env : Env) (st : DevState) {w o}
    (h : dev_transition env st .WriteWifi = ok (w, o)) :
    o = Outcome.PersistThenReset Key.Wifi ∧ ∃ n, w = some n ∧ n.reset_pending = true

theorem reads_store_nothing (env : Env) (st : DevState) (cmd : DevCmd)
    (hc : cmd = .ReadSettings ∨ cmd = .ReadRgb ∨ cmd = .ReadInfo) {w o}
    (h : dev_transition env st cmd = ok (w, o)) : w = none

enable_config.kernel_code:
pub fn enable_config() -> Config {
    set_bits(
        set_bits(with_low(config_new(), SHUTDOWN), IT_MASK, IT_100MS),
        GAIN_MASK,
        GAIN_ONE,
    )
}

with_low.kernel_code:
pub fn with_low(c: Config, mask: u16) -> Config {
    Config { bits: c.bits & !mask }
}

with_low.lean:
def with_low (c : Config) (mask : Std.U16) : Result Config := do
  let i ← lift (~~~ mask)
  let i1 ← lift (c.bits &&& i)
  ok { bits := i1 }

Config.kernel_code:
pub struct Config {
