gain_bits.kernel_code:
pub fn gain_bits(g: Gain) -> u16 {
    match g {
        Gain::OneEighth => GAIN_ONE_EIGHTH,
        Gain::OneQuarter => GAIN_ONE_QUARTER,
        Gain::One => GAIN_ONE,
        Gain::Two => GAIN_TWO,
    }
}

Spool.kernel_code:
pub struct Spool {
    pub host_set: bool,
    /// The host is an IPv4 address (the Spoolman client connects to an
    /// address; upstream parses it with `unwrap`).
    pub host_ipv4: bool,
    pub port_set: bool,
}

set_bits.kernel_code:
pub fn set_bits(c: Config, mask: u16, value: u16) -> Config {
    Config { bits: (c.bits & !mask) | (value & mask) }
}

set_bits.lean:
def set_bits
  (c : Config) (mask : Std.U16) (value : Std.U16) : Result Config := do
  let i ← lift (~~~ mask)
  let i1 ← lift (c.bits &&& i)
  let i2 ← lift (value &&& mask)
  let i3 ← lift (i1 ||| i2)
  ok { bits := i3 }

set_it_config.kernel_code:
pub fn set_it_config(c: Config, it: IntegrationTime) -> Config {
