boot_wifi.kernel_code:
pub fn boot_wifi(has_creds: bool, connected: bool, got_ip: bool) -> BootWifi {
    if !has_creds {
        BootWifi::AccessPoint
    } else if !connected {
        BootWifi::ForgetAndReset
    } else if !got_ip {
        BootWifi::ForgetAndReset
    } else {
        BootWifi::Station
    }
}

BootWifi.kernel_code:
pub enum BootWifi {
    /// No credentials: the open access point `Td-Free`.
    AccessPoint,
    /// Connected with an address: station mode.
    Station,
    /// The stored credentials did not work: delete them and reset (the next
    /// boot is an access point).
    ForgetAndReset,
}

